# Glossary of key terms, each linked to the lab where it is practised.
glossary <- list(
  list(tr("A/B test", "Test A/B"), tr("A randomised experiment that compares two versions of a design on a predefined metric.", "Experimento aleatorizado que compara dos versiones de un diseño con una métrica definida de antemano."), "ab_testing"),
  list(tr("Accessibility", "Accesibilidad"), tr("The degree to which people with the widest range of abilities can perceive, operate and understand a product.", "Grado en que personas con la mayor diversidad de capacidades pueden percibir, manejar y entender un producto."), "accessibility"),
  list(tr("Adjusted Wald interval", "Intervalo de Wald ajustado"), tr("A confidence interval for proportions that works well with small samples, recommended for completion rates.", "Intervalo de confianza para proporciones que funciona bien con muestras pequeñas; recomendado para tasas de éxito."), "ux_metrics"),
  list(tr("Affinity diagram", "Diagrama de afinidad"), tr("Clustering research notes bottom-up by similarity to find themes.", "Agrupar notas de investigación de abajo arriba por similitud para encontrar temas."), "personas"),
  list(tr("Card sorting", "Card sorting"), tr("A method where participants group content cards, revealing their mental model of a domain.", "Método en el que los participantes agrupan tarjetas de contenido, lo que revela su modelo mental de un ámbito."), "information_architecture"),
  list(tr("Confirmshaming", "Confirmshaming"), tr("A deceptive pattern that words the option to decline so as to make people feel guilty.", "Patrón engañoso que redacta la opción de rechazo para hacer sentir culpable a la persona."), "dark_patterns"),
  list(tr("Contrast ratio", "Relación de contraste"), tr("The luminance ratio between text and background, from 1:1 to 21:1. WCAG AA asks for 4.5:1 for normal text.", "Relación de luminancia entre texto y fondo, de 1:1 a 21:1. WCAG AA pide 4,5:1 para texto normal."), "accessibility"),
  list(tr("Dark pattern (deceptive design)", "Patrón oscuro (diseño engañoso)"), tr("An interface that tricks or pressures people into choices against their interests.", "Interfaz que engaña o presiona a la gente para que tome decisiones contrarias a sus intereses."), "dark_patterns"),
  list(tr("Diary study", "Estudio de diario"), tr("Participants record experiences over days or weeks, capturing behaviour in context and over time.", "Los participantes registran sus experiencias durante días o semanas, captando el comportamiento en contexto y en el tiempo."), "research_methods"),
  list(tr("Double-barrelled question", "Pregunta doble"), tr("A question that asks about two things at once, so the answer cannot be interpreted.", "Pregunta sobre dos cosas a la vez, cuya respuesta no se puede interpretar."), "interviews"),
  list(tr("Fitts's law", "Ley de Fitts"), tr("Pointing time grows with log2(distance/width + 1): large, close targets are faster.", "El tiempo de apuntado crece con log2(distancia/ancho + 1): los objetivos grandes y cercanos son más rápidos."), "laws_of_ux"),
  list(tr("Funnel", "Embudo"), tr("A count of how many people complete each step of a flow, used to locate drop-off.", "Recuento de cuántas personas completan cada paso de un flujo; sirve para localizar abandonos."), "user_behaviour"),
  list(tr("Gulf of evaluation", "Golfo de evaluación"), tr("The effort needed to tell whether an action worked (Norman). Feedback narrows it.", "El esfuerzo necesario para saber si una acción ha funcionado (Norman). El feedback lo reduce."), "interaction_patterns"),
  list(tr("HEART framework", "Marco HEART"), tr("Google's framework linking Happiness, Engagement, Adoption, Retention and Task success to goals, signals and metrics.", "Marco de Google que vincula felicidad, implicación, adopción, retención y éxito en la tarea con objetivos, señales y métricas."), "user_behaviour"),
  list(tr("Heuristic evaluation", "Evaluación heurística"), tr("An expert inspection of an interface against usability principles such as Nielsen's ten heuristics.", "Inspección experta de una interfaz con principios de usabilidad como las diez heurísticas de Nielsen."), "usability"),
  list(tr("Hick's law", "Ley de Hick"), tr("Decision time grows with log2(n + 1) for n equally likely options.", "El tiempo de decisión crece con log2(n + 1) para n opciones igual de probables."), "laws_of_ux"),
  list(tr("Information scent", "Rastro de información"), tr("How strongly a link or label suggests that the goal lies behind it.", "Cuánto sugiere un enlace o etiqueta que el objetivo está detrás."), "information_architecture"),
  list(tr("Journey map", "Mapa de recorrido"), tr("A visualisation of a person's end-to-end experience across stages, channels and emotions.", "Visualización de la experiencia completa de una persona a través de etapas, canales y emociones."), "journey"),
  list(tr("Leading question", "Pregunta inductora"), tr("A question whose wording suggests the expected answer.", "Pregunta cuya redacción sugiere la respuesta esperada."), "interviews"),
  list(tr("Microcopy", "Microtexto"), tr("Small pieces of interface text: labels, hints, errors and empty states.", "Pequeños textos de la interfaz: etiquetas, ayudas, errores y estados vacíos."), "ux_writing"),
  list(tr("Minimum detectable effect", "Efecto mínimo detectable"), tr("The smallest difference an experiment is planned to detect with a given power.", "La diferencia más pequeña que un experimento está planificado para detectar con una potencia dada."), "ab_testing"),
  list(tr("Peeking", "Mirar antes de tiempo"), tr("Checking an experiment repeatedly and stopping when it looks significant, which inflates false positives.", "Revisar un experimento repetidamente y pararlo cuando parece significativo, lo que dispara los falsos positivos."), "ab_testing"),
  list(tr("Persona", "Persona"), tr("A research-based archetype that summarises the goals, behaviours and frustrations of a user group.", "Arquetipo basado en investigación que resume los objetivos, comportamientos y frustraciones de un grupo de usuarios."), "personas"),
  list(tr("Service blueprint", "Service blueprint"), tr("A journey map extended with the frontstage and backstage processes that deliver each step.", "Mapa de recorrido ampliado con los procesos visibles e internos que hacen posible cada paso."), "journey"),
  list(tr("Severity rating", "Gravedad"), tr("A 0–4 score combining frequency, impact and persistence of a usability problem.", "Puntuación de 0 a 4 que combina frecuencia, impacto y persistencia de un problema de usabilidad."), "usability"),
  list(tr("SUS (System Usability Scale)", "SUS (System Usability Scale)"), tr("A 10-item questionnaire scored 0–100; 68 is the average. It is not a percentage.", "Cuestionario de 10 ítems puntuado de 0 a 100; 68 es la media. No es un porcentaje."), "ux_metrics"),
  list(tr("Think-aloud protocol", "Pensamiento en voz alta"), tr("Participants say what they think while using a product, revealing their reasoning.", "Los participantes dicen lo que piensan mientras usan un producto, lo que revela su razonamiento."), "ux_metrics"),
  list(tr("Tree testing", "Tree testing"), tr("A test of findability in a text-only hierarchy, without visual design.", "Prueba de encontrabilidad en una jerarquía solo de texto, sin diseño visual."), "information_architecture"),
  list(tr("Triangulation", "Triangulación"), tr("Combining methods so that the weaknesses of one are covered by another.", "Combinar métodos para que las debilidades de uno queden cubiertas por otro."), "research_methods"),
  list(tr("Usability", "Usabilidad"), tr("The effectiveness, efficiency and satisfaction with which specified users achieve goals in a context of use (ISO 9241-11).", "Eficacia, eficiencia y satisfacción con que usuarios concretos logran objetivos en un contexto de uso (ISO 9241-11)."), "ux_metrics"),
  list(tr("Visual hierarchy", "Jerarquía visual"), tr("The order in which elements draw attention, set by size, position, contrast and grouping.", "El orden en que los elementos captan la atención, determinado por tamaño, posición, contraste y agrupación."), "wireframing"),
  list(tr("WCAG", "WCAG"), tr("The W3C Web Content Accessibility Guidelines, organised around the POUR principles and levels A, AA and AAA.", "Las Pautas de Accesibilidad para el Contenido Web del W3C, organizadas en torno a los principios POUR y los niveles A, AA y AAA."), "accessibility"),
  list(tr("Wireframe", "Wireframe"), tr("A low-fidelity layout that shows structure and priority, not visual style.", "Maquetación de baja fidelidad que muestra estructura y prioridad, no estilo visual."), "wireframing")
)
